 /* ---- Split controls (tool-specific; they only write the page box) ---- */
 function drawSplitControls(){
  controls.innerHTML='<span class="psg-count" id="psgSelectedCount"></span><button class="btn" type="button" id="psgAll">Select all</button><button class="btn" type="button" id="psgNone">Select none</button>';
  $('psgAll').onclick=function(){splitSelected=new Set(items.map(function(_,i){return i}));syncChecks();updateSplitSpec()};
  $('psgNone').onclick=function(){splitSelected.clear();syncChecks();updateSplitSpec()};
  syncChecks();updateSplitCount()}
 function syncChecks(){Array.from(thumbs.children).forEach(function(t,i){var c=t.querySelector('input');if(c)c.checked=splitSelected.has(i)})}
 function updateSplitCount(){var c=$('psgSelectedCount');if(c)c.textContent=splitSelected.size+' page(s) selected'}
 function updateSplitSpec(){
  var nums=Array.from(splitSelected).sort(function(a,b){return a-b}).map(function(i){return i+1});var ranges=[];
  for(var i=0;i<nums.length;){var j=i;while(j+1<nums.length&&nums[j+1]===nums[j]+1)j++;ranges.push(nums[i]===nums[j]?''+nums[i]:nums[i]+'-'+nums[j]);i=j+1}
  if($('pagespec'))$('pagespec').value=ranges.join(', ');
  updateSplitCount();
  if($('pdfsrun'))$('pdfsrun').disabled=!PS.first()||!splitSelected.size}

 /* ---- Edit PDF: working copy (EP) of the shared PDF, drawn with the same markup ---- */
 function renderEdit(){
  var pending=PS.edit&&PS.edit.pending(),has=lastEdit&&lastEdit.items&&lastEdit.items.length;
  if(!has&&!pending){hideGallery();clearView();items=[];return}
  showGallery();
  if(pending){clearView();items=[];meta.textContent='Preparing pages for editing…';hint.textContent=EDIT_HINT;stage.innerHTML='<div class="psg-empty">Preparing pages for editing…</div>';return}
  drawEdit(lastEdit)}
 function drawEdit(data){
  pdfEditGalleryUrls.forEach(function(u){try{URL.revokeObjectURL(u)}catch(e){}});pdfEditGalleryUrls=[];
  var generation=++pdfEditPreviewGeneration,arr=data.items||[];
  items=[];clearView();title.textContent='PDF Edit Gallery';
  meta.textContent=arr.length+' page(s)'+(data.name?' · '+data.name:'')+(arr.length?(data.edited?' · working version (edited, not saved yet)':' · original pages'):'');
  hint.textContent=EDIT_HINT;
  if(!arr.length){stage.innerHTML='<div class="psg-empty">Select a PDF or add images to see the pages here.</div>';return}
  active=Math.max(0,Math.min(arr.length-1,Number(data.selected)||0));
  arr.forEach(function(it,i){
   var nd=makeNode(i,it.label||('Page '+(i+1)),it.label||('Page '+(i+1)));
   if(it.blob){var fullUrl=URL.createObjectURL(it.blob);pdfEditGalleryUrls.push(fullUrl);nd.im.src=fullUrl}else{nd.im.src=it.thumb||''}
   nd.ti.src=it.thumb||'';nd.page.classList.add('psg-ready');
   if(it.rot&&!it.blob){pdfEditRotatedPreview(it.thumb,it.rot,function(rotated){if(generation!==pdfEditPreviewGeneration)return;nd.im.src=rotated;nd.ti.src=rotated})}
   nd.th.addEventListener('click',function(){var cards=document.querySelectorAll('#epGrid [data-sel]');if(cards[i])cards[i].click()});
   nd.page.addEventListener('click',function(){var cards=document.querySelectorAll('#epGrid [data-sel]');if(cards[i])cards[i].click()})});
  var selected=stage.children[active];if(selected)centerIn(stage,selected,'y')}
 // Rotate PDF page previews in their actual pixel dimensions, not just the thumbnail CSS.
 function pdfEditRotatedPreview(src,degrees,done){
  var angle=((Number(degrees)||0)%360+360)%360;
  if(!angle){done(src);return}
  var picture=new Image();
  picture.onload=function(){
   var canvas=document.createElement('canvas'),quarter=angle===90||angle===270;
   canvas.width=quarter?picture.naturalHeight:picture.naturalWidth;
   canvas.height=quarter?picture.naturalWidth:picture.naturalHeight;
   var ctx=canvas.getContext('2d');ctx.translate(canvas.width/2,canvas.height/2);
   ctx.rotate(angle*Math.PI/180);
   ctx.drawImage(picture,-picture.naturalWidth/2,-picture.naturalHeight/2);
   done(canvas.toDataURL('image/jpeg',0.92));
  };
  picture.onerror=function(){done(src)};
  picture.src=src;
 }
