/* window.LovePDFi: thin facade. The tools are DOM-driven (state lives in the page's file picker), so each call
 * presses the page's own Run button for that tool. Returns true if a button was found and enabled. */
(function(){
  function run(kind){
    var b=document.querySelector('[data-run="'+kind+'"]');
    if(!b||b.disabled)return false;
    b.click();return true;
  }
  window.LovePDFi=window.LovePDFi||{};
  window.LovePDFi.compress=function(){return run('compress')};
  window.LovePDFi.resize=function(){return run('resize')};
  window.LovePDFi.convert=function(){return run('convert')};
})();
